WITH ranked AS MATERIALIZED (SELECT row_number() OVER(ORDER BY record.time,record.id) AS rank, record.time,account.steam_name,account.discord_id FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) pb JOIN (SELECT * FROM public.record WHERE record_eligible) record ON record.id=pb.id_record JOIN public."user" account ON account.id=pb.id_user JOIN public.level level ON level.id=pb.id_level AND level.publicly_visible=true WHERE pb.id_level=$1), page AS (SELECT * FROM ranked ORDER BY rank LIMIT $2 OFFSET $3) SELECT jsonb_build_object('totalCount',(SELECT count(*) FROM ranked),'rows',COALESCE(jsonb_agg( jsonb_build_object('rank',page.rank,'time',page.time,'steamName',page.steam_name, 'discordId',page.discord_id::text) ORDER BY page.rank),'[]'::jsonb)) AS value FROM page
